def top_k_frequent(nums, k):
    # Create a min heap
    min_heap = []
    # Iterate through the list of numbers
    for num in nums:
        # If the number is not in the min heap, add it
        if num not in min_heap:
            min_heap.append(num)
        # If the number is in the min heap, pop the smallest number
        else:
            # If the number of the smallest number is less than k, pop it
            if len(min_heap) < k:
                min_heap.pop()
            # If the number of the smallest number is equal to k, add it to the heap
            else:
                min_heap.append(num)
    # Return the top k numbers
    return min_heap

def max_Prime_Factors(n):
    factors = []
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return max(factors)

