def max_len_sub(arr, diff):
    n = len(arr)
    dp = [[0 for _ in range(diff + 1)] for _ in range(n)]
    for i in range(n):
        dp[i][0] = 1
    for i in range(1, n):
        for j in range(1, diff + 1):
            if arr[i - 1] + j <= diff:
                dp[i][j] = dp[i - 1][j] + (1 if arr[i] + j == diff else 0)
            else:
                dp[i][j] = dp[i - 1][j]
    return max(dp[n - 1])

