def comb_sort(lst):
    """Sorts a list of elements using comb sort."""
    n = len(lst)
    gap = n
    swapped = False
    while gap > 1 or swapped:
        gap = int(gap / 1.3)
        swapped = False
        for i in range(0, gap):
            if lst[i] > lst[i + 1]:
                lst[i], lst[i + 1] = lst[i + 1], lst[i]
                swapped = True
        if gap == 1:
            break
    return lst

