    count_ones = 0
    count_zeros = 0
    max_diff = 0
    for i in range(len(s)-n+1):
        if s[i] == '0':
            count_zeros += 1
        else:
            count_ones += 1
        if count_ones > count_zeros:
            max_diff = max(max_diff, count_ones - count_zeros)
        else:
            max_diff = max(max_diff, count_zeros - count_ones)
    return max_diff

