def heapify(heap, n, i):
    largest = i
    l = 2 * i + 1
    r = 2 * i + 2
    if l < n and heap[l][1] > heap[i][1]:
        largest = l
    if r < n and heap[r][1] > heap[largest][1]:
        largest = r
    if largest != i:
        heap[i], heap[largest] = heap[largest], heap[i]
        heapify(heap, n, largest)

