    # Create a dictionary to store the frequency of each element
    freq = {}
    for num in arr:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Create a list to store the possible sums
    possible_sums = []
    for i in range(target+1):
        possible_sums.append(i)

    # Iterate through all possible sums
    for i in range(target+1):
        # Check if the sum is possible
        if i == sum:
            return True
        # Check if the sum is possible with the current element
        elif i < sum and i in possible_sums:
            # Check if the current element is in the dictionary
            if i - freq[arr[i]] >= 0:
                # Check if the current element is in the dictionary
                if i - freq[arr[i]] in possible_sums:
                    return True
    return False

